Input: {"question": "Where is Chesapeake High School located?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 0, "end": 151, "text": "Chesapeake High School (Baltimore County) Chesapeake High School (CHS), is a four-year public high school in Baltimore County, Maryland, United States."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 152, "end": 288, "text": "Chesapeake High School is one of two high schools in Maryland by that name, the other being Chesapeake High School, Anne Arundel County."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 289, "end": 400, "text": "The Chesapeake High School of Baltimore County is located in southeast corner of the county in Essex, Maryland."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 401, "end": 539, "text": "The school borders the school districts of Kenwood High School, Sparrows Point High School, Dundalk High School, and Patapsco High School."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 540, "end": 593, "text": "Widely known for its Virtual Lab and MCJROTC program."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 594, "end": 617, "text": "The high school is on ."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0481-ab574ac174f6:d00", "start": 618, "end": 632, "text": "Chesapeake has"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0481-ab574ac174f6:d01", "start": 0, "end": 141, "text": "Chesapeake High School (Baltimore County) Chesapeake High School (CHS), is a four-year public high school in Orlando, Florida, United States."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0481-ab574ac174f6:d01", "start": 142, "end": 278, "text": "Chesapeake High School is one of two high schools in Maryland by that name, the other being Chesapeake High School, Anne Arundel County."}, 